/* markdown 排版：只保留品牌所需的间距与层级 */
.md {
  font-size: var(--text-sm);
  line-height: 1.85;
  color: var(--color-fg);
}
.md > * + * {
  margin-top: 0.9em;
}
.md h1,
.md h2,
.md h3,
.md h4 {
  font-weight: 600;
  line-height: 1.4;
  margin-top: 1.6em;
}
.md h1 {
  font-size: 1.35em;
}
.md h2 {
  font-size: 1.15em;
}
.md h3 {
  font-size: 1.02em;
}
.md ul,
.md ol {
  padding-left: 1.4em;
}
.md ul {
  list-style: disc;
}
.md ol {
  list-style: decimal;
}
.md li + li {
  margin-top: 0.35em;
}
.md a {
  color: var(--color-link);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.md code {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  background: var(--color-sunken);
  border-radius: 4px;
  padding: 0.12em 0.36em;
}
.md pre code {
  background: transparent;
  padding: 0;
}
.md blockquote {
  border-left: 2px solid var(--color-edge);
  padding-left: 1em;
  color: var(--color-muted);
}
.md hr {
  border: 0;
  border-top: 1px solid var(--color-edge);
}
.md table {
  border-collapse: collapse;
  font-size: 0.95em;
}
.md th,
.md td {
  border: 1px solid var(--color-edge);
  padding: 0.4em 0.7em;
  text-align: left;
}
.md th {
  background: var(--color-sunken);
  font-weight: 600;
}

/* 流式光标 */
.streaming::after {
  content: '';
